import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Check, Clock3, Filter, Gauge, MessageSquareText } from "lucide-react";
import { Card } from "@/components/ui/Card";
import { AppPageHero } from "@/components/app/AppPageHero";
import { ButtonLink } from "@/components/ui/Button";
import { portalRepository } from "@/services/supabase/portal";
import { usePageMeta } from "@/hooks/usePageMeta";

export default function TrackingPage() {
  const [filter, setFilter] = useState<"all" | "done" | "current" | "upcoming">("all");
  const { data, error } = useQuery({ queryKey: ["portal", "snapshot"], queryFn: portalRepository.getSnapshot });
  const timeline = data?.timeline ?? [];
  const visible = filter === "all" ? timeline : timeline.filter((event) => event.state === filter);
  const progress = data?.project?.progress ?? 0;
  usePageMeta("Suivi du projet", "Consultez les événements serveur et les prochaines étapes du projet.");
  return <div className="mx-auto max-w-6xl space-y-5"><AppPageHero icon={Gauge} eyebrow="Chronologie du projet" title={<>Chaque événement reste <span className="gradient-text">compréhensible.</span></>} description="Les changements opérationnels et actions documentaires alimentent cette chronologie sans promettre les délais d’une administration externe." stat={{ value: `${progress}%`, label: "Progression" }} action={<label className="inline-flex h-11 items-center gap-2 rounded-full border border-white/12 bg-white/[.07] px-4 text-sm font-semibold text-white"><Filter className="size-4" /><select value={filter} onChange={(event) => setFilter(event.target.value as typeof filter)} className="bg-transparent outline-none"><option value="all" className="text-[color:var(--ink)]">Tous</option><option value="done" className="text-[color:var(--ink)]">Terminés</option><option value="current" className="text-[color:var(--ink)]">Actuels</option><option value="upcoming" className="text-[color:var(--ink)]">À venir</option></select></label>} />{error ? <Card className="p-5 text-[color:var(--blue)]">{error instanceof Error ? error.message : "Chargement impossible"}</Card> : null}<div className="grid gap-5 lg:grid-cols-[1fr_320px]"><Card className="p-6 sm:p-8"><div className="space-y-0">{visible.map((event, index) => <div key={event.id} className="relative flex gap-5 pb-8 last:pb-0"><div className="relative"><span className={`relative z-10 grid size-11 place-items-center rounded-full border-4 border-white ${event.state === "done" ? "bg-[var(--mint)]" : event.state === "current" ? "bg-[var(--blue)] text-white" : "bg-[var(--paper)]"}`}>{event.state === "done" ? <Check className="size-4" /> : event.state === "current" ? <Clock3 className="size-4" /> : index + 1}</span>{index < visible.length - 1 ? <span className="absolute left-1/2 top-10 h-full w-px bg-[var(--line)]" /> : null}</div><div className="flex-1 rounded-[22px] border border-[var(--line)] bg-white p-4"><h2 className="font-semibold">{event.title}</h2><p className="mt-2 text-sm leading-6 text-[color:var(--muted)]">{event.description}</p><p className="mt-3 text-xs text-[color:var(--muted)]">{new Date(event.date).toLocaleString("fr-FR")}</p></div></div>)}{visible.length === 0 ? <p className="py-12 text-center text-sm text-[color:var(--muted)]">Aucun événement dans cette catégorie.</p> : null}</div></Card><div className="space-y-5"><Card className="p-6"><p className="text-xs font-semibold uppercase tracking-[.13em] text-[color:var(--muted)]">Progression</p><p className="mt-3 text-4xl font-semibold">{progress}%</p><div className="mt-4 h-2 rounded-full bg-[var(--ink)]/8"><div className="h-full rounded-full bg-[var(--mint)]" style={{ width: `${progress}%` }} /></div></Card><Card className="p-6"><h3 className="font-semibold">Une question sur une étape ?</h3><p className="mt-3 text-sm leading-6 text-[color:var(--muted)]">La messagerie conserve votre demande dans le contexte du projet.</p><ButtonLink to="/app/messages" variant="secondary" className="mt-5 w-full"><MessageSquareText className="size-4" />Écrire à l’équipe</ButtonLink></Card></div></div></div>;
}
